-- ============================================================================
-- Grand Test Script for MGD_LNP_PK Package
-- Registration: XWM00003001200
--
-- Inserts test data into ALL tables so that every stored procedure in
-- MGD_LNP_PK returns data with all applicable charge codes.
--
-- IMPORTANT: All dates are set within the MGD period window which is derived
-- from paye_data.safe_lp_sequence. Currently: 01-OCT-2013 to 31-DEC-2014.
-- If the period window changes, charge_date / payment_post_date /
-- reallocation_date values may need adjusting.
--
-- Tables populated:
--   1. MGD_OPERATOR_DETAILS   (getMGDOperatorDetails)
--   2. MGD_LP_TOTAL           (14 sprocs use totals)
--   3. MGD_LP_CHARGE          (C-type: all 6 codes, I-type: all 6 codes, R-type: all 6 codes)
--   4. MGD_LP_ACCRUING_INTEREST (getMGDAccruingDrilldown, getMGDInterestAccruingDetails)
--   5. MGD_LP_LATE_PAY_INTEREST (getMGDInterestDetails, getMGDInterestDrilldown)
--   6. MGD_LP_PAYMENT           (getMGDPayments, getMGDReallocationsInDetails)
--   7. MGD_LP_PAYMENT_ON_ACCOUNT (getMGDPayments, getMGDReallocationsInDetails)
--   8. MGD_LP_REALLOCATION_OUT   (getMGDActualRepayments, getMGDReallocationsOutDetails,
--                                  getMGDRepaymentInterestRepaid)
--   9. MGD_RETURN_DETAILS        (getMGDCurrentPosition)
--
-- Charge codes covered (SAFE_MTRANS_CODE):
--   1940 - PPLR interest bearing
--   1950 - Return Charge
--   1960 - Central Assessment
--   1970 - Officer Assessment
--   1980 - Late Filing Penalty
--   1990 - Late Payment Penalty
--
-- Safe to run multiple times — deletes all existing data first, then inserts.
-- ============================================================================

SET DEFINE OFF;

-- ============================================================================
-- 0. CLEAN SLATE — Delete all existing data for XWM00003001200
--    Order matters: delete from child tables first to avoid FK issues.
-- ============================================================================
DELETE FROM mgd_lp_accruing_interest WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_late_pay_interest WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_payment WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_payment_on_account WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_reallocation_out WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_charge WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_lp_total WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_return_details WHERE mgd_reg_number = 'XWM00003001200';
DELETE FROM mgd_operator_details WHERE mgd_reg_number = 'XWM00003001200';
COMMIT;

