-- ============================================================================
-- SPROC COVERAGE SUMMARY
-- ============================================================================
-- 1.  getMGDPeriods                  - paye_data.safe_lp_sequence (pre-existing)
-- 2.  getMGDAccountOverview          - MGD_LP_TOTAL + MGD_OPERATOR_DETAILS
-- 3.  getMGDAccruingDrilldown        - MGD_LP_CHARGE(C) + MGD_LP_ACCRUING_INTEREST
-- 4.  getMGDActualRepayments         - MGD_LP_TOTAL + MGD_LP_REALLOCATION_OUT(R,null)
-- 5.  getMGDAssessmentsWithoutReturn - MGD_LP_TOTAL + MGD_LP_CHARGE(C,1960)
-- 6.  getMGDCurrentPosition          - MGD_LP_TOTAL + MGD_RETURN_DETAILS
-- 7.  getMGDInterestAccruingDetails  - MGD_LP_CHARGE(C,interest-bearing)
-- 8.  getMGDInterestDetails          - MGD_LP_TOTAL + MGD_LP_CHARGE(I)
-- 9.  getMGDInterestDrilldown        - MGD_LP_LATE_PAY_INTEREST + MGD_LP_CHARGE
-- 10. getMGDInterestOverview         - MGD_LP_TOTAL + getAccruingIntTotal
-- 11. getMGDOperatorDetails          - MGD_OPERATOR_DETAILS
-- 12. getMGDPayments                 - MGD_LP_PAYMENT + MGD_LP_PAYMENT_ON_ACCOUNT
-- 13. getMGDPenalties                - MGD_LP_TOTAL + MGD_LP_CHARGE(C,1980/1990,sub=1090)
-- 14. getMGDReallocationsDetails     - MGD_LP_TOTAL
-- 15. getMGDReallocationsInDetails   - MGD_LP_PAYMENT(R) + MGD_LP_PAYMENT_ON_ACCOUNT(R)
-- 16. getMGDReallocationsOutDetails  - MGD_LP_REALLOCATION_OUT(O)
-- 17. getMGDRepaymentSummary         - MGD_LP_TOTAL
-- 18. getMGDRepaymentDrilldown       - STUB (returns 0 by design)
-- 19. getMGDRepaymentInterestDetails - MGD_LP_CHARGE(R) - all 6 codes
-- 20. getMGDRepaymentInterestRepaid  - MGD_LP_REALLOCATION_OUT(R,I)
-- 21. getMGDReturnsSubmitted         - MGD_LP_CHARGE(C,1950)
-- 22. getOtherAssessmentDetails      - MGD_LP_CHARGE(C,1970)
-- 23. version (x2)                   - No data needed
-- 24. getAccruingIntTotal            - Calls getMGDInterestAccruingDetails
-- ============================================================================
